        /* COLLAPSED MENU TEXT HIDING */
        html body.sidebar-collapsed:not(.xxx):not(.yyy) #sidebar .sidebar-menu a span,
        html[lang] body.sidebar-collapsed:not(.xxx):not(.yyy) #sidebar .sidebar-menu a span,
        html[data-lang] body.sidebar-collapsed:not(.xxx):not(.yyy) #sidebar .sidebar-menu a span {
            opacity: 0 !important;
