        }

        /* MAIN CONTENT POSITIONING - ULTRA HIGH SPECIFICITY */
        html body:not(.sidebar-collapsed):not(.sidebar-hidden):not(.xxx):not(.yyy) .dashboard-wrp,
        html[lang] body:not(.sidebar-collapsed):not(.sidebar-hidden):not(.xxx):not(.yyy) .dashboard-wrp,
        html[data-lang] body:not(.sidebar-collapsed):not(.sidebar-hidden):not(.xxx):not(.yyy) .dashboard-wrp,
        html body:not(.sidebar-collapsed):not(.sidebar-hidden):not(.xxx):not(.yyy) .page-wrapper,
        html[lang] body:not(.sidebar-collapsed):not(.sidebar-hidden):not(.xxx):not(.yyy) .page-wrapper {
            margin-left: 250px !important;
            width: calc(100vw - 250px) !important;
            max-width: calc(100vw - 250px) !important;
            transition: all 0.3s ease !important;
            min-height: 100vh !important;
        }

        /* COLLAPSED CONTENT POSITIONING */
        html body.sidebar-collapsed:not(.xxx):not(.yyy) .dashboard-wrp,
        html[lang] body.sidebar-collapsed:not(.xxx):not(.yyy) .dashboard-wrp,
        html[data-lang] body.sidebar-collapsed:not(.xxx):not(.yyy) .dashboard-wrp,
        html body.sidebar-collapsed:not(.xxx):not(.yyy) .page-wrapper,
        html[lang] body.sidebar-collapsed:not(.xxx):not(.yyy) .page-wrapper {
            margin-left: 60px !important;
            width: calc(100vw - 60px) !important;
            max-width: calc(100vw - 60px) !important;
        }

        /* HIDDEN CONTENT POSITIONING */
        html body.sidebar-hidden:not(.xxx):not(.yyy) .dashboard-wrp,
        html[lang] body.sidebar-hidden:not(.xxx):not(.yyy) .dashboard-wrp,
        html[data-lang] body.sidebar-hidden:not(.xxx):not(.yyy) .dashboard-wrp,
        html body.sidebar-hidden:not(.xxx):not(.yyy) .page-wrapper,
        html[lang] body.sidebar-hidden:not(.xxx):not(.yyy) .page-wrapper {
            margin-left: 0 !important;
            width: 100vw !important;
            max-width: 100vw !important;
        }

        /* TOGGLE BUTTON POSITIONING */
        html body:not(.xxx):not(.yyy) #toggle-sidenav,
        html[lang] body:not(.xxx):not(.yyy) #toggle-sidenav,
        html[data-lang] body:not(.xxx):not(.yyy) #toggle-sidenav {
            position: fixed !important;
            top: 20px !important;
            left: 260px !important;
            z-index: 1001 !important;
            background: #2563eb !important;
            color: white !important;
