        }

        html body.sidebar-collapsed:not(.xxx):not(.yyy) #toggle-sidenav {
            left: 70px !important;
        }

        html body.sidebar-hidden:not(.xxx):not(.yyy) #toggle-sidenav {
            left: 20px !important;
        }
    `;

    // Inject CSS with maximum priority
    function injectRobustCSS() {
        try {
            const style = document.createElement('style');
            style.setAttribute('data-sidebar-robust', 'true');
            style.setAttribute('type', 'text/css');
            style.textContent = ROBUST_CSS;

            if (document.head) {
                document.head.appendChild(style);
                styleSheets.push(style);
                console.log('🛡️ Robust sidebar CSS injected successfully');
            } else {
                setTimeout(injectRobustCSS, 100);
            }
        } catch(e) {
            console.error('❌ Failed to inject robust CSS:', e);
            setTimeout(injectRobustCSS, 200);
        }
    }

    // Force correct inline styles as backup
    function enforceInlineStyles(state = currentState) {
        const sidebar = document.getElementById('sidebar');
        const content = document.querySelector('.dashboard-wrp') || document.querySelector('.page-wrapper');
        const toggleBtn = document.getElementById('toggle-sidenav');

        if (!sidebar) {
            setTimeout(() => enforceInlineStyles(state), 100);
            return;
        }

        // Force sidebar styles
        switch(state) {
            case 'collapsed':
                sidebar.style.cssText = `
                    position: fixed !important;
                    left: 0 !important;
                    top: 0 !important;
                    width: 60px !important;
                    height: 100vh !important;
                    background: white !important;
                    z-index: 999 !important;
                    transform: translateX(0) !important;
                    border-right: 1px solid #e2e8f0 !important;
                    overflow: visible !important;
                `;
                if (content) {
                    content.style.cssText = `
                        margin-left: 60px !important;
                        width: calc(100vw - 60px) !important;
                        max-width: calc(100vw - 60px) !important;
                        transition: all 0.3s ease !important;
                    `;
                }
                if (toggleBtn) {
                    toggleBtn.style.left = '70px !important';
                }
                break;

            case 'hidden':
                sidebar.style.cssText = `
                    position: fixed !important;
                    left: 0 !important;
                    top: 0 !important;
                    width: 250px !important;
                    height: 100vh !important;
                    background: white !important;
                    z-index: 999 !important;
                    transform: translateX(-100%) !important;
                    border-right: 1px solid #e2e8f0 !important;
                    overflow: visible !important;
                `;
                if (content) {
                    content.style.cssText = `
                        margin-left: 0 !important;
                        width: 100vw !important;
                        max-width: 100vw !important;
                        transition: all 0.3s ease !important;
                    `;
                }
                if (toggleBtn) {
                    toggleBtn.style.left = '20px !important';
                }
                break;

            case 'expanded':
            default:
                sidebar.style.cssText = `
                    position: fixed !important;
                    left: 0 !important;
                    top: 0 !important;
                    width: 250px !important;
                    height: 100vh !important;
                    background: white !important;
                    z-index: 999 !important;
                    transform: translateX(0) !important;
                    border-right: 1px solid #e2e8f0 !important;
                    overflow: visible !important;
                `;
                if (content) {
                    content.style.cssText = `
                        margin-left: 250px !important;
                        width: calc(100vw - 250px) !important;
                        max-width: calc(100vw - 250px) !important;
                        transition: all 0.3s ease !important;
                    `;
                }
                if (toggleBtn) {
                    toggleBtn.style.left = '260px !important';
                }
                break;
        }

        // Force menu items visibility
        const menuItems = sidebar.querySelectorAll('.sidebar-menu a');
        menuItems.forEach(item => {
            item.style.cssText = `
                display: flex !important;
                visibility: visible !important;
                opacity: 1 !important;
                padding: 0.75rem 1rem !important;
                color: #64748b !important;
                align-items: center !important;
                gap: 0.75rem !important;
                width: 100% !important;
            `;
        });

        console.log(`🔧 Enforced inline styles for state: ${state}`);
    }

    // Set sidebar state with maximum enforcement
    function setSidebarState(state) {
        console.log(`🎯 Setting sidebar state to: ${state}`);
        currentState = state;

        // Apply CSS classes
        document.body.classList.remove('sidebar-collapsed', 'sidebar-hidden');
        if (state === 'collapsed') {
            document.body.classList.add('sidebar-collapsed');
        } else if (state === 'hidden') {
            document.body.classList.add('sidebar-hidden');
        }

        // Force inline styles as backup
        enforceInlineStyles(state);

        // Save state
        try {
            localStorage.setItem('sidebarState', state);
        } catch(e) {
            console.warn('Could not save sidebar state');
        }

        // Force redraw
        setTimeout(() => {
            window.dispatchEvent(new Event('resize'));
        }, 100);
    }

    // Monitor for external changes and fight them
    function setupDefensiveMonitoring() {
        // Style monitoring
        setInterval(() => {
            if (!forceActive) return;

            const sidebar = document.getElementById('sidebar');
            if (sidebar) {
                const computedStyle = window.getComputedStyle(sidebar);
                const expectedWidth = currentState === 'collapsed' ? '60px' : 
                                    currentState === 'hidden' ? '250px' : '250px';
                const expectedTransform = currentState === 'hidden' ? 'translateX(-100%)' : 'translateX(0px)';

                if (computedStyle.width !== expectedWidth || 
                    computedStyle.transform !== expectedTransform) {
                    console.log('🚨 Sidebar style corruption detected, fixing...');
                    enforceInlineStyles(currentState);
                }
            }
        }, 500);

        // Mutation observer for DOM changes
        if (window.MutationObserver && !mutationObserver) {
            mutationObserver = new MutationObserver((mutations) => {
                let needsReinforcement = false;

                mutations.forEach((mutation) => {
                    if (mutation.type === 'attributes' && 
                        mutation.target.id === 'sidebar' &&
                        (mutation.attributeName === 'style' || mutation.attributeName === 'class')) {
                        needsReinforcement = true;
                    }
                });

                if (needsReinforcement && forceActive) {
                    console.log('🔄 DOM mutation detected, reinforcing styles...');
                    setTimeout(() => enforceInlineStyles(currentState), 50);
                }
            });

            mutationObserver.observe(document.body, {
                attributes: true,
                attributeFilter: ['style', 'class'],
                subtree: true
            });
        }
    }

    // Setup toggle button event
    function setupToggleButton() {
        const toggleBtn = document.getElementById('toggle-sidenav');
        if (toggleBtn) {
            toggleBtn.addEventListener('click', function(e) {
                e.preventDefault();
                e.stopPropagation();

                switch(currentState) {
                    case 'expanded':
                        setSidebarState('collapsed');
                        break;
                    case 'collapsed':
                        setSidebarState('hidden');
                        break;
                    case 'hidden':
                        setSidebarState('expanded');
