// ===== ENHANCED SIDEBAR & TABLE MANAGEMENT SYSTEM =====

// Enhanced Sidebar Toggle for Your POS System
function initializeSidebarControl() {
    // Wait for DOM and all scripts to be fully loaded
    const sidebar = document.getElementById('sidebar');
    const pageWrapper = document.querySelector('.dashboard-wrp, .page-wrapper, .content-area, .main-wrapper');
    const existingToggle = document.getElementById('toggle-sidenav');
    const mobileBtn = document.getElementById('mobile_btn');

    // Verify required elements exist
    if (!sidebar) {
        console.warn('Sidebar element #sidebar not found - retrying in 100ms');
        setTimeout(initializeSidebarControl, 100);
        return;
    }

    if (!pageWrapper) {
        console.warn('Page wrapper not found - retrying in 100ms');
        setTimeout(initializeSidebarControl, 100);
        return;
    }

    console.log('Sidebar elements found, initializing...');

    // Remove any auto-created toggle button
    const autoCreatedToggle = document.querySelector('.sidebar-toggle');
    if (autoCreatedToggle && autoCreatedToggle.parentNode) {
        autoCreatedToggle.parentNode.removeChild(autoCreatedToggle);
    }

    // State management
    let currentState = 'expanded'; // expanded, collapsed, hidden

    // Set the sidebar to a specific state
    function setSidebarState(state) {
        if (!sidebar || !pageWrapper) {
            console.error('Elements not available for state change');
            return;
        }

        // Prevent infinite loops by checking if state is already current
        if (currentState === state) {
            return;
        }

        // Remove all state classes from sidebar
        sidebar.classList.remove('collapsed', 'hidden', 'mobile-open');

        // Remove all state classes from page wrapper and related elements
        pageWrapper.classList.remove('sidebar-collapsed', 'sidebar-hidden');

        // Also apply to document body for global CSS targeting
        document.body.classList.remove('sidebar-collapsed', 'sidebar-hidden');

        // Find and update all main content areas - Enhanced for Malchus
        const contentAreas = document.querySelectorAll('.dashboard-wrp, .content-area, .page-wrapper, .main-wrapper, .content');
        contentAreas.forEach(area => {
            area.classList.remove('sidebar-collapsed', 'sidebar-hidden');
        });

        // Apply new state
        switch(state) {
            case 'collapsed':
                sidebar.classList.add('collapsed');
                pageWrapper.classList.add('sidebar-collapsed');
                document.body.classList.add('sidebar-collapsed');
                contentAreas.forEach(area => {
                    area.classList.add('sidebar-collapsed');
                });
                break;
            case 'hidden':
                sidebar.classList.add('hidden');
                pageWrapper.classList.add('sidebar-hidden');
                document.body.classList.add('sidebar-hidden');
                contentAreas.forEach(area => {
                    area.classList.add('sidebar-hidden');
                });
                break;
            case 'expanded':
            default:
                // Default expanded state - no additional classes needed
                // Force removal of any lingering classes
                sidebar.classList.remove('collapsed', 'hidden');
                document.body.classList.remove('sidebar-collapsed', 'sidebar-hidden');
                contentAreas.forEach(area => {
                    area.classList.remove('sidebar-collapsed', 'sidebar-hidden');
                });
                break;
        }

        currentState = state;
        try {
            localStorage.setItem('sidebarState', state);
        } catch(e) {
            console.warn('Could not save sidebar state:', e);
        }

        // Force DataTables to recalculate column widths after layout change
        setTimeout(() => {
            if (window.$ && $.fn.DataTable) {
                $.fn.DataTable.tables({ visible: true, api: true }).columns.adjust();
            }

            // Trigger a window resize event to help other components adjust
            window.dispatchEvent(new Event('resize'));
        }, 350);

        console.log('Sidebar state changed to:', state);
    }

    // Handle the main toggle click (cycles through states)
    function handleToggleClick(e) {
        if (e) {
            e.preventDefault();
            e.stopPropagation();
        }

        switch(currentState) {
            case 'expanded':
                setSidebarState('collapsed');
                break;
            case 'collapsed':
                setSidebarState('hidden');
                break;
            case 'hidden':
                setSidebarState('expanded');
                break;
        }
    }

    // Setup submenu toggles - Enhanced for multiple selector patterns
    function setupSubmenuToggles() {
        // Look for multiple possible patterns for submenu items
        const submenuSelectors = [
            '.has-sub > a',           // Original pattern
            '.submenu > a',           // Alternative pattern
            '.sidebar-menu li:has(ul) > a', // Items with UL children
            '.menu-item:has(.sub-menu) > a', // Items with sub-menu class
            'li:has(.dropdown-menu) > a',    // Bootstrap-style dropdowns
            'li > a + ul',            // Adjacent sibling pattern
            '[data-submenu] > a',     // Data attribute pattern
        ];

        let foundItems = [];

        // Fallback: Look for any link that has a sibling UL or parent with submenu indicators
        const allLinks = document.querySelectorAll('#sidebar a, .sidebar a, .sidebar-menu a');
        allLinks.forEach(link => {
            const parent = link.parentElement;
            const nextSibling = link.nextElementSibling;
            const hasSubmenu = nextSibling && (
                nextSibling.tagName === 'UL' || 
                nextSibling.classList.contains('sub-menu') ||
                nextSibling.classList.contains('dropdown-menu')
            );

            // Also check if parent has submenu children
            const hasSubmenuChildren = parent && (
                parent.querySelector('ul') ||
                parent.querySelector('.sub-menu') ||
                parent.querySelector('.dropdown-menu')
            );

            if (hasSubmenu || hasSubmenuChildren) {
                foundItems.push(link);
            }
        });

        console.log(`Found ${foundItems.length} submenu items`);

        foundItems.forEach(link => {
            // Remove any existing event listeners by cloning
            const newLink = link.cloneNode(true);
            if (link.parentNode) {
                link.parentNode.replaceChild(newLink, link);
            }

            newLink.addEventListener('click', function(e) {
                // Only prevent default if we're not in collapsed mode and this is actually a submenu toggle
                const parent = this.parentElement;
                const nextSibling = this.nextElementSibling;
                const hasSubmenu = nextSibling && (
                    nextSibling.tagName === 'UL' || 
                    nextSibling.classList.contains('sub-menu') ||
                    nextSibling.classList.contains('dropdown-menu')
                ) || parent.querySelector('ul, .sub-menu, .dropdown-menu');

                if (hasSubmenu && currentState !== 'collapsed') {
                    e.preventDefault();
                    e.stopPropagation();

                    const isOpen = parent.classList.contains('open') || parent.classList.contains('active');

                    // Close all other submenus
                    document.querySelectorAll('.open, .active').forEach(item => {
                        if (item !== parent && (item.querySelector('ul') || item.querySelector('.sub-menu'))) {
                            item.classList.remove('open', 'active');
                        }
                    });

                    // Toggle current submenu
                    if (isOpen) {
                        parent.classList.remove('open', 'active');
                    } else {
                        parent.classList.add('open', 'active');
                    }

                    console.log(`Toggled submenu for: ${this.textContent.trim()}`);
                }
            });
        });

        // Add visual indicators for submenu items
        foundItems.forEach(link => {
            const parent = link.parentElement;
            const nextSibling = link.nextElementSibling;
            const hasSubmenu = nextSibling && (
                nextSibling.tagName === 'UL' || 
                nextSibling.classList.contains('sub-menu') ||
                nextSibling.classList.contains('dropdown-menu')
            ) || parent.querySelector('ul, .sub-menu, .dropdown-menu');

            if (hasSubmenu && !link.querySelector('.dropdown-indicator')) {
                // Add dropdown indicator if it doesn't exist
                const indicator = document.createElement('span');
                indicator.className = 'dropdown-indicator';
                indicator.innerHTML = '▶';
                indicator.style.marginLeft = 'auto';
                indicator.style.fontSize = '12px';
                indicator.style.transition = 'transform 0.2s ease';
                link.appendChild(indicator);

                // Update indicator based on state
                if (parent.classList.contains('open') || parent.classList.contains('active')) {
                    indicator.style.transform = 'rotate(90deg)';
                }
            }
        });
    }

    // Setup event listeners
    function setupEventListeners() {
        // Main toggle button (desktop)
        if (existingToggle) {
            existingToggle.addEventListener('click', handleToggleClick);

            // Add right-click context menu
            existingToggle.addEventListener('contextmenu', function(e) {
                e.preventDefault();
                if (window.sidebarControl && window.sidebarControl.showConfig) {
                    window.sidebarControl.showConfig();
                }
            });

            // Add tooltip
            existingToggle.title = `Sidebar Toggle\nLeft: Toggle • Right: Settings\nAlt+M: Toggle • Alt+C: Collapse • Alt+E: Expand • Alt+H: Hide`;

            console.log('Added click handler to existing toggle');
        } else {
            console.warn('Existing toggle button not found');
        }

        // Handle submenu toggles
        setupSubmenuToggles();

        // Enhanced keyboard support
        document.addEventListener('keydown', function(e) {
            // Alt + M to toggle sidebar
            if (e.altKey && e.key === 'm') {
                e.preventDefault();
                handleToggleClick(e);
            }

            // Alt + C to collapse sidebar
            if (e.altKey && e.key === 'c') {
                e.preventDefault();
                setSidebarState('collapsed');
            }

            // Alt + E to expand sidebar
            if (e.altKey && e.key === 'e') {
                e.preventDefault();
                setSidebarState('expanded');
            }

            // Alt + H to hide sidebar
            if (e.altKey && e.key === 'h') {
                e.preventDefault();
                setSidebarState('hidden');
            }

            // Escape to close mobile sidebar
            if (e.key === 'Escape' && window.innerWidth <= 768 && currentState !== 'hidden') {
                setSidebarState('hidden');
            }
        });
    }

    // Initialize the sidebar system
    function initializeSidebar() {
        // Get saved state or default to expanded
        let savedState = 'expanded';
        try {
            savedState = localStorage.getItem('sidebarState') || 'expanded';
        } catch(e) {
            console.warn('Could not read saved sidebar state:', e);
        }

        setSidebarState(savedState);
        setupEventListeners();

        console.log('Sidebar initialization complete');
    }

    // Start initialization
    initializeSidebar();

    // Make functions available globally for debugging and API access
    window.sidebarControl = {
        setState: setSidebarState,
        getState: () => currentState,
        toggle: handleToggleClick
    };
}

// TABLE FUNCTIONALITY - Wait for the table to be ready
function waitForTable() {
    const table = document.getElementById('so-items-table');
    if (table) {
        initializeTableFeatures(table);
    } else {
        // Retry after a short delay
        setTimeout(waitForTable, 100);
    }
}

